/* Operazioni titoli, chiusura reversibile dei conti e scelte archiviate. */
(()=>{'use strict';const W=TFWorkflow;
 for(const name of ['editPosition','editUtility','editBill']){const original=({editPosition,editUtility,editBill})[name];const wrap=function(...args){original(...args);const form=$('#positionForm,#utilityForm,#billForm');if(form)form.dataset.editingExisting=args[0]?'1':'0'};if(name==='editPosition')editPosition=wrap;if(name==='editUtility')editUtility=wrap;if(name==='editBill')editBill=wrap;}
 function splitRowHTML(row={}){return '<div class="form-grid allocation-row" data-split-row><label>Conto<select data-split="account">'+state.accounts.map(a=>'<option value="'+esc(a.name)+'" '+(a.name===(row.account||'')?'selected':'')+'>'+esc(a.name)+'</option>').join('')+'</select></label><label>Categoria'+categoryInput(row.category||'Altro','data-split="category" aria-label="Categoria" required maxlength="70"')+'</label><label>Quota EUR<input data-split="amount" type="number" min="0.01" step=".01" value="'+(Number(row.amount)||'')+'" inputmode="decimal"></label><button class="btn" type="button" data-remove-split aria-label="Rimuovi quota">×</button></div>'}
 const originalMovement=editMovement;
 editMovement=function(id){
  originalMovement(id);const form=$('#movementForm');if(!form)return;
  const old=state.movements.find(m=>m.id===id),type=form.elements.type,amount=form.elements.amount;
  const box=document.createElement('fieldset');box.id='tradeCalculation';box.className='notice';
  box.innerHTML='<legend>Quantità, prezzo e commissione</legend><div class="form-grid"><label>Operazione sui titoli<select name="tradeSide"><option value="buy">Acquisto</option><option value="sell">Vendita</option></select></label><label>Numero titoli<input name="securityQty" type="number" min="0.00000001" step="any" inputmode="decimal"></label><label>Prezzo per titolo EUR<input name="securityUnitPrice" type="number" min="0" step="any" inputmode="decimal"></label><label>Commissione facoltativa EUR<input name="tradeCommission" type="number" min="0" step=".01" inputmode="decimal"></label><label>Addebita la commissione su<select name="commissionAccount">'+state.accounts.map(a=>'<option value="'+esc(a.name)+'">'+esc(a.name)+'</option>').join('')+'</select></label></div><p class="small">Quantità × prezzo calcola l’importo dei titoli; puoi anche inserire il totale e ricavare il prezzo unitario. La commissione viene registrata a parte come “Spese bancarie”, così non duplica il valore dell’investimento. Se lasci quantità o prezzo vuoti, il movimento si salva ma il dossier non si aggiorna: la panoramica ti segnala le operazioni da completare.</p><p class="small" id="tradeCalculationResult" role="status"></p>';
  $('#movementHelp').before(box);const splitGroup=old?.splitGroupId?state.movements.filter(row=>row.splitGroupId===old.splitGroupId):[];const splitBox=document.createElement('fieldset');splitBox.id='movementAllocations';splitBox.className='notice';splitBox.innerHTML='<legend>Ripartisci per conto o categoria</legend><label class="check"><input id="splitEnabled" type="checkbox" '+(splitGroup.length?'checked':'')+'> Dividi questa operazione in più quote</label><p class="small">Le quote, anche con conti o categorie diverse, devono sommare al totale. Per un trasferimento successivo tra conti usa “Giroconto”.</p><div id="splitRows"></div><button type="button" class="btn" id="addSplitRow">＋ Aggiungi quota</button><p class="small" id="splitCheck" role="status"></p>';$('#movementHelp').before(splitBox);const splitRows=$('#splitRows'),splitEnabled=$('#splitEnabled');if(splitGroup.length){splitRows.innerHTML=splitGroup.map(splitRowHTML).join('');amount.value=String(splitGroup.reduce((sum,row)=>sum+Math.abs(Number(row.amount)||0),0))}else splitRows.innerHTML=splitRowHTML({account:form.elements.account.value,category:form.elements.category.value});const refreshSplits=()=>{const active=splitEnabled.checked&&['Spesa','Entrata'].includes(type.value);splitRows.hidden=!active;$('#addSplitRow').hidden=!active;const total=[...splitRows.querySelectorAll('[data-split=amount]')].reduce((n,input)=>n+(Number(input.value)||0),0);$('#splitCheck').textContent=active?'Quote inserite: '+euro(total)+' · Totale operazione: '+euro(Math.abs(Number(amount.value)||0)):'La ripartizione è facoltativa.'};splitEnabled.onchange=refreshSplits;$('#addSplitRow').onclick=()=>{splitRows.insertAdjacentHTML('beforeend',splitRowHTML({account:form.elements.account.value,category:form.elements.category.value}));refreshSplits()};splitRows.onclick=e=>{if(e.target.closest('[data-remove-split]')){if(splitRows.querySelectorAll('[data-split-row]').length<2)return toast('Mantieni almeno una quota.');e.target.closest('[data-split-row]').remove();refreshSplits()}};splitRows.oninput=refreshSplits;splitRows.onchange=refreshSplits;amount.addEventListener('input',refreshSplits);type.addEventListener('change',refreshSplits);refreshSplits();const qty=form.elements.securityQty,unit=form.elements.securityUnitPrice,side=form.elements.tradeSide,commission=form.elements.tradeCommission,commissionAccount=form.elements.commissionAccount;
  side.value=old?.tradeSide||(Number(old?.amount||0)>0?'sell':'buy');qty.value=old?.securityQty??'';unit.value=old?.securityUnitPrice??'';commission.value=old?.tradeCommission??'';const defaultCommissionAccount=()=>{const source=state.accounts.find(a=>a.name===form.elements.account.value),cash=state.accounts.filter(a=>!a.closed&&a.kind==='Conto corrente'&&source&&String(a.bank||'').toLowerCase()===String(source.bank||'').toLowerCase());if(source?.kind==='Titoli'&&cash.length===1)return cash[0].name;return source?.name||form.elements.account.value};commissionAccount.value=old?.commissionAccount||defaultCommissionAccount();if(old?.commissionAccount)commissionAccount.dataset.userChoice='1';commissionAccount.addEventListener('change',()=>commissionAccount.dataset.userChoice='1');form.elements.account.addEventListener('change',()=>{if(!commissionAccount.dataset.userChoice)commissionAccount.value=defaultCommissionAccount()});
  // Recover an explicit quantity from imported trade descriptions, when present.
  if(!qty.value){const match=String(old?.description||'').match(/(?:quantity\s*:|qta\s*\/\s*val[.]?nom[.]?)\s*([\d.,]+)/i);if(match)qty.value=String(Number(match[1].replace(',','.')))}
  let basis='total';const visible=()=>{box.hidden=type.value!=='Investimento';qty.disabled=unit.disabled=side.disabled=commission.disabled=commissionAccount.disabled=box.hidden};
  function calculate(changed){if(box.hidden)return;if(changed==='unitPrice')basis='unitPrice';if(changed==='total')basis='total';if(!qty.value){$('#tradeCalculationResult').textContent='Indica il numero di titoli per il calcolo.';return}if(basis==='unitPrice'&&!unit.value)return;const r=W.trade({qty:qty.value,unitPrice:unit.value,total:amount.value,commission:commission.value,side:side.value,changed:basis});if(!r)return;if(changed!=='total')amount.value=String(r.amount);if(basis==='total')unit.value=String(Number(r.unitPrice.toPrecision(12)));$('#tradeCalculationResult').textContent=num(r.qty)+' × '+num(r.unitPrice)+' € = '+euro(r.total)+' titoli · commissione '+euro(r.commission)+' · prezzo effettivo '+num(r.effectiveUnitPrice)+' €/titolo · impatto netto '+euro(r.netAmount)+' · '+(side.value==='sell'?'Vendita':'Acquisto')}
  qty.addEventListener('input',()=>calculate('qty'));unit.addEventListener('input',()=>calculate('unitPrice'));commission.addEventListener('input',()=>calculate('commission'));amount.addEventListener('input',()=>{calculate('total')});side.addEventListener('change',()=>calculate('side'));const category=form.elements.category;type.addEventListener('change',()=>{if(type.value==='Investimento')category.value='Investimenti';else if(category.value==='Investimenti')category.value='Altro'});category.addEventListener('change',()=>{if(category.value==='Investimenti'&&type.value!=='Investimento'){type.value='Investimento';type.dispatchEvent(new Event('change',{bubbles:true}))}});const updateAmountLabel=()=>{if($('#amountLabel'))$('#amountLabel').textContent=type.value==='Investimento'?'Importo titoli · commissione esclusa EUR':(['Spesa','Entrata','Giroconto'].includes(type.value)?'Importo EUR':'Importo con segno EUR')};type.addEventListener('change',()=>{visible();updateAmountLabel();calculate('total')});visible();updateAmountLabel();if(qty.value)calculate('total');
  form.addEventListener('submit',e=>{if(box.hidden)return;if(!qty.value&&!unit.value)return;if(unit.value!==''&&(!Number.isFinite(Number(unit.value))||Number(unit.value)<0)){e.preventDefault();e.stopImmediatePropagation();unit.focus();toast('Il prezzo per titolo deve essere un numero non negativo.');return}const r=W.trade({qty:qty.value,unitPrice:unit.value,total:amount.value,commission:commission.value,side:side.value,changed:'total'});if(!r){e.preventDefault();e.stopImmediatePropagation();qty.focus();toast('Inserisci una quantità di titoli maggiore di zero.');return}qty.value=String(r.qty);unit.value=String(r.unitPrice);amount.value=String(r.amount);form.elements.tradeCommission.value=String(r.commission);form.elements.commissionAccount.value=commissionAccount.value},{capture:true});
 };
 document.addEventListener('click',async e=>{const b=e.target.closest('[data-account-close]');if(!b)return;const a=state.accounts.find(a=>a.id===b.dataset.accountClose);if(!a)return;const closed=!a.closed;if(!confirm(closed?'Chiudere il conto '+a.name+'? Storico, documenti, posizioni e saldo restano conservati. Potrai riaprirlo.':'Riaprire il conto '+a.name+'?'))return;if(await change(s=>W.setClosed(s,a.id,closed,today()),[],{skipDuplicateReview:true}))toast(closed?'Conto chiuso. Puoi riaprirlo dalla sua scheda.':'Conto riaperto.')});
 function providerChoices(form){const input=form.querySelector('input[name="provider"]');if(!input||input.dataset.archivedReady)return;input.dataset.archivedReady='1';const values=W.choices(state).providers,list=document.createElement('datalist');list.id=form.id+'ProviderChoices';list.innerHTML=values.map(v=>'<option value="'+esc(v)+'">').join('');input.setAttribute('list',list.id);input.after(list);const select=document.createElement('select');select.className='suggestion-select';select.setAttribute('aria-label','Scegli un fornitore archiviato');select.innerHTML=suggestionOptions(values);select.onchange=()=>{if(select.value)input.value=select.value};list.after(select)}
 document.addEventListener('submit',e=>{const form=e.target;if(!form.matches('#positionForm,#utilityForm,#billForm,#transferForm'))return;const existing=form.dataset.editingExisting==='1';if(existing)return;const names=['account','from','to'],ids=['accountId'];if(names.some(n=>state.accounts.find(a=>a.name===form.elements[n]?.value)?.closed)||ids.some(n=>state.accounts.find(a=>a.id===form.elements[n]?.value)?.closed)){e.preventDefault();e.stopImmediatePropagation();toast('Il conto è chiuso: riaprilo prima di aggiungere nuovi dati.')}},{capture:true});
 const observer=new MutationObserver(()=>{for(const form of $$('#billForm,#utilityForm'))providerChoices(form)});observer.observe(document.body,{childList:true,subtree:true});
})();
